// src/App.jsx
import React, { Suspense } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import MainPage from './pages/MainPage';
import './config/config';             // ← 여기서 config.js 를 메인 번들에 포함

const HyOrderCalculator = React.lazy(() => import('./calculators/HyOrderCalculator'));
const TVBizCalculator = React.lazy(() => import('./calculators/TVBizCalculator'));
const InternetCalculator = React.lazy(() => import('./calculators/InternetCalculator'));
const TvmCalculator = React.lazy(() => import('./calculators/TvmCalculator'));
const PhoneSalesCalculator = React.lazy(() => import('./calculators/PhoneSalesCalculator'));
const KTBundlingCalculator = React.lazy(() => import('./calculators/KTBundlingCalculator'));
export default function App() {
  return (
    <BrowserRouter>
      <Suspense fallback={<div>로딩 중…</div>}>
        <Routes>
          <Route path="/" element={<MainPage />} />
          <Route path="/hiorder"    element={<HyOrderCalculator />} />
          <Route path="/tvbiz"      element={<TVBizCalculator />} />
          <Route path="/internet"   element={<InternetCalculator />} />
          <Route path="/tvm"        element={<TvmCalculator />} />
          <Route path="/mobile"     element={<PhoneSalesCalculator />} />
          <Route path="/bundle"     element={<KTBundlingCalculator />} />  
          <Route path="*"           element={<MainPage />} />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
}

